import { describe, expect, it } from 'vitest';
import { defaultSetupModel } from '../shared/setup-models.js';
import { sidekickPreset, sidekickPresetNotice } from '../shared/setup.js';

const catalog = (...ids: string[]) => ids.map(id => ({id}));
describe('automatic Sidekick setup', () => {
  it('picks Astra 6 and Sol 6, with Sidekick Fusion and Shunt off', () => {
    const preset = sidekickPreset('gateway',catalog('anthropic/claude-fable-5-1','anthropic/claude-opus-5-5','openai/gpt-6-sol','openai/gpt-6-astra','gpt-6-astra','gpt-5.6-sol'));
    expect(preset).toMatchObject({providerId:'gateway',model:'openai/gpt-6-astra',architecture:{kind:'sidekick-fusion',sidekick:{providerId:'gateway',model:'openai/gpt-6-sol'}},shunt:{enabled:false}});
    expect(sidekickPresetNotice(preset)).toBe('');
  });
  it('falls back to Fable and Opus independently, then to each remaining family', () => {
    const models = catalog('claude-fable-5-1','claude-opus-5-5');
    expect(defaultSetupModel(models,'driver')).toBe('claude-fable-5-1');
    expect(defaultSetupModel(models,'sidekick')).toBe('claude-opus-5-5');
    expect(defaultSetupModel([...models,{id:'gpt-6-astra'}],'sidekick')).toBe('claude-opus-5-5');
    expect(defaultSetupModel(catalog('claude-opus-5-5','gpt-6-sol'),'driver')).toBe('claude-opus-5-5');
    for (const id of ['gpt-6-astra','claude-fable-5-1','claude-opus-5-5','gpt-6-sol']) {
      expect(defaultSetupModel(catalog(id),'driver')).toBe(id);
    }
    for (const id of ['gpt-6-sol','claude-opus-5-5','claude-sonnet-5']) {
      expect(defaultSetupModel(catalog(id),'sidekick')).toBe(id);
    }
  });
  it('uses Sol, then Opus, then the latest Sonnet for the sidekick', () => {
    const sonnets=catalog('anthropic/claude-3-5-sonnet-20241022','anthropic/claude-sonnet-4-5','anthropic/claude-sonnet-4-6','anthropic/claude-sonnet-5');
    expect(defaultSetupModel(sonnets,'sidekick')).toBe('anthropic/claude-sonnet-5');
    expect(defaultSetupModel([...sonnets,{id:'claude-opus-5-5'}],'sidekick')).toBe('claude-opus-5-5');
    expect(defaultSetupModel([...sonnets,{id:'claude-opus-5-5'},{id:'gpt-6-sol'}],'sidekick')).toBe('gpt-6-sol');
    expect(defaultSetupModel(catalog('gpt-6-astra','claude-fable-5-1'),'sidekick')).toBe('');
    const missingSidekick=sidekickPreset('gateway',catalog('gpt-6-astra'));
    expect(missingSidekick.model).toBe('gpt-6-astra');
    expect(sidekickPresetNotice(missingSidekick)).toContain('Choose a model for your sidekick.');
    const missingDriver=sidekickPreset('gateway',sonnets);
    expect(missingDriver.model).toBe('');
    expect(sidekickPresetNotice(missingDriver)).toContain('Choose a model for your driver.');
  });
  it('prioritizes family before version and compares version components numerically', () => {
    expect(defaultSetupModel(catalog('gpt-5-astra','claude-fable-6','claude-opus-7'),'driver')).toBe('gpt-5-astra');
    expect(defaultSetupModel(catalog('claude-fable-5-9','claude-fable-5-10','claude-fable-5-1-20260922'),'driver')).toBe('claude-fable-5-10');
    expect(defaultSetupModel(catalog('gpt-5.6-sol','gpt-6-sol','gpt-6.1-sol'),'sidekick')).toBe('gpt-6.1-sol');
  });
  it('handles dated versions, provider prefixes, legacy names and explicit aliases', () => {
    expect(defaultSetupModel(catalog('claude-opus-4-5-20251101','claude-opus-4-6-20260205','claude-3-opus-20240229'),'driver')).toBe('claude-opus-4-6-20260205');
    expect(defaultSetupModel(catalog('claude-fable-5-1-20260901','claude-fable-5-1-20260922'),'driver')).toBe('claude-fable-5-1-20260922');
    expect(defaultSetupModel(catalog('bedrock/global.anthropic.claude-fable-5-1-v1:0','openrouter/anthropic/claude-fable-5.1'),'driver')).toBeTruthy();
    expect(defaultSetupModel([{id:'team-lead',canonicalId:'openai/gpt-6-astra'}],'driver')).toBe('team-lead');
  });
  it('does not guess from display labels, partial names or unsupported variants', () => {
    const models = catalog('my-astra','claude-fable-5-1-thinking','gpt-6-sol-mini','batch/openai/gpt-6-astra','claude-opus-5-5-batch','unknown');
    models.push({id:'custom'});
    const preset = sidekickPreset('gateway',models);
    expect(preset.model).toBe('');
    expect(preset.architecture).toMatchObject({sidekick:{model:''}});
    expect(sidekickPresetNotice(preset)).toContain('Choose a model for your driver and sidekick');
    expect(defaultSetupModel([],'driver')).toBe('');
  });
});

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { createServer, type Server } from 'node:http';
import { mkdtemp, mkdir, realpath, rm, readFile, writeFile } from 'node:fs/promises';
import { execFile } from 'node:child_process';
import { promisify } from 'node:util';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { Store } from '../server/store.js';
import { createApp } from '../server/app.js';

const exec = promisify(execFile);
describe('Git action workspace coordination', () => {
  let root: string, workspace: string, base: string, store: Store, server: Server, application: ReturnType<typeof createApp>;
  beforeEach(async () => {
    vi.stubEnv('GIT_CONFIG_NOSYSTEM', '1'); vi.stubEnv('GIT_CONFIG_GLOBAL', '/dev/null');
    root = await realpath(await mkdtemp(join(tmpdir(), 'litespeed-git-api-'))); workspace = join(root, 'project'); await mkdir(workspace);
    await exec('git', ['init', '-b', 'main'], { cwd: workspace }); await writeFile(join(workspace, 'first.txt'), 'first\n');
    store = new Store(join(root, 'state')); store.saveSettings({ workspace }); application = createApp({ store }); server = createServer(application.app);
    await new Promise<void>(resolve => server.listen(0, '127.0.0.1', resolve)); base = `http://127.0.0.1:${(server.address() as { port: number }).port}`;
  });
  afterEach(async () => { await application.schedules.stop(); application.runner.stopAll(); server.closeAllConnections(); await new Promise<void>(resolve => server.close(() => resolve())); store.close(); await rm(root, { recursive: true, force: true }); vi.unstubAllEnvs(); });
  const post = async (path: string, data: unknown) => { const response = await fetch(base + path, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) }); return { status: response.status, data: await response.json() }; };
  it('prepares and applies fixed actions, requiring an issued one-use plan', async () => {
    const prepared = await post('/api/git/actions/prepare', { workspace, action: 'stage', paths: ['first.txt'] }); expect(prepared.status).toBe(200);
    expect((await post('/api/git/actions/apply', { workspace, id: prepared.data.id })).status).toBe(200);
    expect((await exec('git', ['show', ':first.txt'], { cwd: workspace })).stdout).toBe('first\n');
    expect((await post('/api/git/actions/apply', { workspace, id: prepared.data.id })).status).toBe(409);
    expect((await post('/api/git/actions/prepare', { workspace, action: 'reset --hard' })).status).toBe(400);
  });
  it('rejects Git actions during a session operation and serializes project operations', async () => {
    const session = store.createSession({ workspace }); let release!: () => void;
    const held = application.runner.exclusive(session.id, () => new Promise<void>(resolve => { release = resolve; }));
    try { expect((await post('/api/git/actions/prepare', { workspace, action: 'stage', paths: ['first.txt'] })).status).toBe(409); }
    finally { release(); await held; }
    const heldProject = application.runner.workspaceOperation(workspace, () => new Promise<void>(resolve => { release = resolve; }));
    try { expect((await post('/api/git/actions/prepare', { workspace, action: 'stage', paths: ['first.txt'] })).status).toBe(409); await expect(application.runner.exclusive(session.id, async () => undefined)).rejects.toThrow('Another task'); }
    finally { release(); await heldProject; }
    expect((await post('/api/git/actions/prepare', { workspace, action: 'stage', paths: ['first.txt'] })).status).toBe(200);
  });
  it('does not run actions while a background project command is active', async () => {
    const session = store.createSession({ workspace }); const job = application.runner.jobs.start(session.id, 'sleep 30', workspace, { hidden: true });
    try { expect((await post('/api/git/actions/prepare', { workspace, action: 'stage', paths: ['first.txt'] })).status).toBe(409); }
    finally { application.runner.jobs.kill(session.id, job.id); }
  });
  it('reviews, discards and restores with task coordination and project-scoped original downloads', async () => {
    const prepared = await post('/api/git/discards/prepare', { workspace, paths: ['first.txt'] }); expect(prepared.status).toBe(200);
    const session = store.createSession({ workspace }); let release!: () => void;
    const held = application.runner.exclusive(session.id, () => new Promise<void>(resolve => { release = resolve; }));
    try { expect((await post('/api/git/discards/apply', { workspace, id: prepared.data.id })).status).toBe(409); } finally { release(); await held; }
    const applied = await post('/api/git/discards/apply', { workspace, id: prepared.data.id }); expect(applied.status).toBe(200); await expect(readFile(join(workspace, 'first.txt'))).rejects.toThrow();
    const download = await fetch(`${base}/api/git/discards/${applied.data.backup.id}/original?${new URLSearchParams({ workspace, path: 'first.txt' })}`); expect(download.status).toBe(200); expect(download.headers.get('Content-Disposition')).toContain('attachment'); expect(download.headers.get('Content-Security-Policy')).toContain('sandbox'); expect(await download.text()).toBe('first\n');
    const foreign = await fetch(`${base}/api/git/discards/${applied.data.backup.id}/original?${new URLSearchParams({ workspace: root, path: 'first.txt' })}`); expect(foreign.status).toBe(404);
    const restored = await post(`/api/git/discards/${applied.data.backup.id}/restore`, { workspace }); expect(restored.status).toBe(200); expect((await post('/api/git/discards/apply', { workspace, id: restored.data.id })).status).toBe(200); expect(await readFile(join(workspace, 'first.txt'), 'utf8')).toBe('first\n');
    expect((await fetch(`${base}/api/git/discards/${applied.data.backup.id}`, { method: 'DELETE', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ workspace }) })).status).toBe(400);
    expect((await fetch(`${base}/api/git/discards/${applied.data.backup.id}`, { method: 'DELETE', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ workspace, confirm: true }) })).status).toBe(200); expect(await readFile(join(workspace, 'first.txt'), 'utf8')).toBe('first\n');
  });

  it('keeps original copies and cleanup available after a project folder disappears', async () => {
    const plan = await post('/api/git/discards/prepare', { workspace, paths: ['first.txt'] });
    const result = await post('/api/git/discards/apply', { workspace, id: plan.data.id }); await rm(workspace, { recursive: true });
    const all = await (await fetch(base + '/api/git/discards?all=true')).json(); expect(all.backups[0]).toMatchObject({ workspace, id: result.data.backup.id });
    const copy = await fetch(`${base}/api/git/discards/${result.data.backup.id}/original?${new URLSearchParams({ workspace, path: 'first.txt' })}`); expect(copy.status).toBe(200); expect(await copy.text()).toBe('first\n');
    const restore = await post(`/api/git/discards/${result.data.backup.id}/restore`, { workspace }); expect(restore.status).toBe(409); expect(restore.data.error).toContain('folder is unavailable');
    expect((await fetch(`${base}/api/git/discards/${result.data.backup.id}`, { method: 'DELETE', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ workspace, confirm: true }) })).status).toBe(200);
    expect((await (await fetch(base + '/api/git/discards?all=true')).json()).backups).toEqual([]);
  });

  it('coordinates reviewed branch changes with tasks and background project work', async () => {
    const git = (...args: string[]) => exec('git', args, { cwd: workspace });
    await git('config', 'user.name', 'Test'); await git('config', 'user.email', 'test@example.com'); await git('add', '.'); await git('commit', '-m', 'Initial');
    const listing = await (await fetch(`${base}/api/git/branches?${new URLSearchParams({ workspace })}`)).json(); expect(listing.current).toBe('main');
    const plan = await post('/api/git/branches/prepare', { workspace, request: { action: 'create', name: 'feature' } }); expect(plan.status).toBe(200);
    const session = store.createSession({ workspace }); let release!: () => void;
    const held = application.runner.exclusive(session.id, () => new Promise<void>(resolve => { release = resolve; }));
    try { expect((await post('/api/git/branches/apply', { workspace, id: plan.data.id })).status).toBe(409); } finally { release(); await held; }
    expect((await post('/api/git/branches/apply', { workspace, id: plan.data.id })).data.current).toBe('feature');
    const job = application.runner.jobs.start(session.id, 'sleep 30', workspace, { hidden: true });
    try { expect((await post('/api/git/branches/prepare', { workspace, request: { action: 'switch', ref: 'refs/heads/main' } })).status).toBe(409); } finally { application.runner.jobs.kill(session.id, job.id); }
    expect((await post('/api/git/branches/prepare', { workspace, request: { action: 'force', ref: 'refs/heads/main' } })).status).toBe(400);
  });

});

import { afterEach, describe, expect, it } from 'vitest';
import { createServer } from 'node:http';
import { createHash, randomUUID } from 'node:crypto';
import { mkdtemp, readFile, stat, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { Server } from '@modelcontextprotocol/sdk/server/index.js';
import { StreamableHTTPServerTransport } from '@modelcontextprotocol/sdk/server/streamableHttp.js';
import { CallToolRequestSchema, ListToolsRequestSchema, isInitializeRequest } from '@modelcontextprotocol/sdk/types.js';
import { createApp } from '../server/app.js';
import { Store } from '../server/store.js';
import { McpAuth } from '../server/mcp-auth.js';
import { McpManager } from '../server/mcp.js';
import { connectionError } from '../server/mcp-errors.js';
import type { McpServerConfig } from '../shared/types.js';

const cleanup: (() => Promise<unknown>)[] = [];
const signal = () => new AbortController().signal;
afterEach(async () => { for (const close of cleanup.splice(0).reverse()) await close(); });
async function fixture(options: { expires?: number; rejectRefresh?: boolean; rejectCall?: boolean; echoToken?: boolean } = {}) {
  const directory = await mkdtemp(join(tmpdir(), 'litespeed-mcp-auth-'));
  cleanup.push(() => rm(directory, { recursive: true, force: true }));
  const rpcs: string[] = [];
  const requests: string[] = [], grants: string[] = [], authorizations: URL[] = [];
  const sessions = new Map<string, StreamableHTTPServerTransport>(), servers: Server[] = [];
  let base = '', registrations = 0, calls = 0, listings = 0;
  const http = createServer(async (req, res) => {
    try {
      const url = new URL(req.url!, base); requests.push(`${req.method} ${url.pathname}`);
      const chunks: Buffer[] = []; for await (const chunk of req) chunks.push(Buffer.from(chunk));
      const raw = Buffer.concat(chunks).toString();
      const json = (status: number, data: unknown) => { res.writeHead(status, { 'Content-Type': 'application/json' }).end(JSON.stringify(data)); };
      if (url.pathname.startsWith('/.well-known/oauth-protected-resource')) return json(200, { resource: `${base}/mcp`, authorization_servers: [base], scopes_supported: ['read'] });
      if (url.pathname === '/.well-known/oauth-authorization-server') return json(200, { issuer: base, authorization_endpoint: `${base}/authorize`, token_endpoint: `${base}/token`, registration_endpoint: `${base}/register`, response_types_supported: ['code'], grant_types_supported: ['authorization_code', 'refresh_token'], code_challenge_methods_supported: ['S256'], token_endpoint_auth_methods_supported: ['none'] });
      if (url.pathname === '/register') { registrations++; return json(201, { ...JSON.parse(raw), client_id: 'fixture-client' }); }
      if (url.pathname === '/authorize') {
        authorizations.push(url);
        const redirect = new URL(url.searchParams.get('redirect_uri')!); redirect.searchParams.set('state', url.searchParams.get('state')!); redirect.searchParams.set('code', 'fixture-code');
        res.writeHead(302, { Location: redirect.href }).end(); return;
      }
      if (url.pathname === '/token') {
        const params = new URLSearchParams(raw), grant = params.get('grant_type')!; grants.push(grant);
        if (grant === 'authorization_code') {
          const challenge = createHash('sha256').update(params.get('code_verifier')!).digest('base64url');
          if (params.get('code') !== 'fixture-code' || challenge !== authorizations.at(-1)?.searchParams.get('code_challenge')) return json(400, { error: 'invalid_grant' });
        }
        if (grant === 'refresh_token' && options.rejectRefresh) return json(400, { error: 'invalid_grant', error_description: 'DO_NOT_EXPOSE_refresh-secret' });
        return json(200, { access_token: grant === 'refresh_token' ? 'refreshed-secret' : 'access-secret', token_type: 'Bearer', refresh_token: 'refresh-secret', expires_in: grant === 'refresh_token' ? 3600 : options.expires ?? 3600 });
      }
      if (url.pathname === '/mcp') {
        const body = raw ? JSON.parse(raw) : undefined; if (body?.method) rpcs.push(body.method);
        if (!['Bearer access-secret', 'Bearer refreshed-secret'].includes(String(req.headers.authorization)) || (options.rejectCall && body?.method === 'tools/call')) {
          res.setHeader('WWW-Authenticate', `Bearer resource_metadata="${base}/.well-known/oauth-protected-resource"`); return json(401, { error: 'DO_NOT_EXPOSE_access-secret' });
        }
        const id = String(req.headers['mcp-session-id'] || ''); let transport = sessions.get(id);
        if (!transport && isInitializeRequest(body)) {
          const created = new StreamableHTTPServerTransport({ sessionIdGenerator: () => randomUUID(), onsessioninitialized: id => { sessions.set(id, created); } }); transport = created;
          const sdk = new Server({ name: 'oauth-fixture', version: '1.0' }, { capabilities: { tools: {} } }); servers.push(sdk);
          sdk.setRequestHandler(ListToolsRequestSchema, () => { listings++; return { tools: [{ name: 'read', description: 'Read a value', inputSchema: { type: 'object' } }] }; });
          sdk.setRequestHandler(CallToolRequestSchema, () => { calls++; return { content: [{ type: 'text', text: options.echoToken ? 'access-secret' : 'read value' }] }; });
          await sdk.connect(created);
        }
        if (!transport) return json(404, {});
        await transport.handleRequest(req, res, body); return;
      }
      json(404, {});
    } catch { if (!res.headersSent) res.writeHead(500); res.end(); }
  });
  await new Promise<void>(resolve => http.listen(0, '127.0.0.1', resolve)); base = `http://127.0.0.1:${(http.address() as { port: number }).port}`;
  cleanup.push(async () => { await Promise.all(servers.map(server => server.close())); http.closeAllConnections(); await new Promise<void>(resolve => http.close(() => resolve())); });
  const config: Record<string, McpServerConfig> = { remote: { url: `${base}/mcp`, enabled: true } };
  function client() { const auth = new McpAuth(directory), manager = new McpManager(() => config, auth); cleanup.push(() => manager.close()); return { auth, manager }; }
  const { auth, manager } = client();
  const connect = () => manager.reconnect('remote', manager.status()[0].revision, signal());
  const login = () => manager.login('remote', manager.status()[0].revision, signal());
  return { directory, config, auth, manager, client, connect, login, requests, rpcs, grants, authorizations, registrations: () => registrations, calls: () => calls, listings: () => listings };
}

describe('remote MCP OAuth with real discovery, PKCE, callback, and SDK transports', () => {
  it('requires explicit sign-in, validates state, persists private credentials, and reconnects after restart', async () => {
    const f = await fixture();
    await expect(f.connect()).rejects.toThrow('Sign-in required');
    expect(f.manager.status()[0]).toMatchObject({ status: 'auth_required', errorCode: 'auth_required', tools: [] });
    expect(f.registrations()).toBe(0);
    const login = await f.login(), authorize = new URL(login.url);
    expect(authorize.searchParams.get('code_challenge_method')).toBe('S256');
    expect(authorize.searchParams.get('scope')).toBe('read');
    expect(authorize.searchParams.get('resource')).toBe(f.config.remote.url);
    const invalid = new URL(authorize.searchParams.get('redirect_uri')!); invalid.searchParams.set('state', 'incorrect'); invalid.searchParams.set('code', 'fixture-code');
    expect((await fetch(invalid)).status).toBe(400); expect(f.grants).toEqual([]);
    expect(await (await fetch(login.url)).text()).toContain('Signed in');
    expect(f.manager.loginStatus(login.loginId)).toEqual({ status: 'complete' });
    expect(f.listings()).toBe(0); expect(f.calls()).toBe(0);
    const file = join(f.directory, 'mcp-auth.json'); expect((await stat(file)).mode & 0o777).toBe(0o600);
    expect(await readFile(file, 'utf8')).toContain('refresh-secret');
    expect(JSON.stringify(f.manager.status())).not.toContain('access-secret');
    await f.connect(); expect(f.manager.status()[0].status).toBe('connected');
    await f.manager.close();
    const resumed = f.client(); await resumed.manager.reconnect('remote', resumed.manager.status()[0].revision, signal());
    expect(resumed.manager.status()[0].tools).toHaveLength(1); expect(f.registrations()).toBe(1);
  });
  it('coalesces expired-token refresh and never replays a rejected tool request', async () => {
    const f = await fixture({ expires: 0, rejectCall: true }), login = await f.login();
    await fetch(login.url);
    expect(await Promise.all([f.auth.token('remote', f.config.remote.url!), f.auth.token('remote', f.config.remote.url!)])).toEqual(['refreshed-secret', 'refreshed-secret']);
    expect(f.grants).toEqual(['authorization_code', 'refresh_token']);
    await f.connect(); const lease = f.manager.capture(signal());
    await expect(lease.execute(lease.definitions[0].function.name, {}, signal())).rejects.toThrow();
    expect(f.calls()).toBe(0); expect(f.grants).toHaveLength(2); expect(f.rpcs.filter(method => method === 'tools/call')).toHaveLength(1);
    expect(f.manager.status()[0].status).toBe('auth_required');
  });
  it('reports expired authorization without exposing token endpoint errors', async () => {
    const f = await fixture({ expires: 0, rejectRefresh: true }), login = await f.login(); await fetch(login.url);
    await expect(f.connect()).rejects.toThrow('Sign-in required');
    expect(f.manager.status()[0].status).toBe('auth_required');
    expect(JSON.stringify(f.manager.status())).not.toMatch(/secret|DO_NOT_EXPOSE/);
  });
  it('rejects callbacks after configuration changes and cancels pending logins', async () => {
    const f = await fixture(), login = await f.login();
    f.config.remote.enabled = false;
    expect((await fetch(login.url)).status).toBe(409); expect(f.grants).toEqual([]);
    expect(f.manager.loginStatus(login.loginId).status).toBe('error');
    f.config.remote.enabled = true;
    const second = await f.login(); f.manager.cancelLogin(second.loginId);
    expect(f.manager.loginStatus(second.loginId)).toMatchObject({ status: 'error', error: 'Sign-in cancelled.' });
    expect(f.grants).toEqual([]);
  });
  it('invalidates accepted tools and remembered approvals when signing into another account', async () => {
    const f = await fixture({ echoToken: true }), first = await f.login(); await fetch(first.url); await f.connect();
    const lease = f.manager.capture(signal()), tool = lease.definitions[0].function.name, scope = lease.scope(tool);
    expect(await lease.execute(tool, {}, signal())).toBe('[redacted]');
    const second = await f.login(); await fetch(second.url);
    expect(() => lease.assertCurrent(tool)).toThrow();
    await f.connect(); const fresh = f.manager.capture(signal()); expect(fresh.scope(tool)).not.toBe(scope);
    await f.manager.logout('remote', f.manager.status()[0].revision, signal());
    expect(() => fresh.assertCurrent(tool)).toThrow();
    expect(await f.auth.token('remote', f.config.remote.url!)).toBeUndefined();
    const resumed = f.client(); expect(await resumed.auth.token('remote', f.config.remote.url!)).toBeUndefined();
  });
  it('keeps authorization bound to the configured server identity', async () => {
    const f = await fixture(), login = await f.login(); await fetch(login.url);
    expect(await f.auth.token('different-name', f.config.remote.url!)).toBeUndefined();
    expect(await f.auth.token('remote', f.config.remote.url! + '/different')).toBeUndefined();
    expect(() => f.manager.login('remote', 'stale', signal())).toThrow();
  });
});

describe('safe connection diagnostics', () => {
  it.each([['ENOTFOUND', 'dns'], ['ECONNREFUSED', 'refused'], ['CERT_HAS_EXPIRED', 'tls'], ['UND_ERR_CONNECT_TIMEOUT', 'timeout']] as const)('classifies %s without echoing secrets', (code, expected) => {
